changeSet.sql:
CREATE OR REPLACE FUNCTION queue_media_correlation_for_track()
RETURNS TRIGGER AS $$
BEGIN
    IF TG_OP = 'UPDATE' THEN
        IF ROW(OLD.start_date, OLD.end_date, OLD.load_status, OLD.duplicate_status, OLD.track_source)
           IS NOT DISTINCT FROM
           ROW(NEW.start_date, NEW.end_date, NEW.load_status, NEW.duplicate_status, NEW.track_source) THEN
            RETURN NEW;
        END IF;
    END IF;
    INSERT INTO media_correlation_track_work(track_id, reason, requested_at)
    VALUES (NEW.id, 'track_' || LOWER(TG_OP), CURRENT_TIMESTAMP)
    ON CONFLICT (track_id) DO UPDATE SET
        reason = EXCLUDED.reason,
        requested_at = EXCLUDED.requested_at;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

